package com.seatease.model;

/**
 * Customer — Represents a customer who makes a booking.
 *
 * OOP Concepts demonstrated:
 * - Encapsulation: private fields with public getters/setters.
 * - Constructor overloading.
 *
 * Stores the customer's name, mobile number, and optional email.
 * The customerId is auto-generated by the database.
 */
public class Customer {

    private int customerId;     // Auto-generated by MySQL
    private String name;        // Required
    private String mobile;      // Required — exactly 10 digits
    private String email;       // Optional

    // Default constructor
    public Customer() {
    }

    // Constructor without ID (used before saving to database)
    public Customer(String name, String mobile, String email) {
        this.name = name;
        this.mobile = mobile;
        this.email = email;
    }

    // Full constructor (used when reading from database)
    public Customer(int customerId, String name, String mobile, String email) {
        this.customerId = customerId;
        this.name = name;
        this.mobile = mobile;
        this.email = email;
    }

    // --- Getters and Setters ---

    public int getCustomerId() {
        return customerId;
    }

    public void setCustomerId(int customerId) {
        this.customerId = customerId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getMobile() {
        return mobile;
    }

    public void setMobile(String mobile) {
        this.mobile = mobile;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    @Override
    public String toString() {
        return "Customer{" +
                "customerId=" + customerId +
                ", name='" + name + '\'' +
                ", mobile='" + mobile + '\'' +
                ", email='" + email + '\'' +
                '}';
    }
}
